import{_ as i,a0 as u,w as l,s as a,ao as s,I as o,a1 as p,A as r,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在 Ubuntu 15.04 上安裝 Justniffer | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 15.04 上安裝 Justniffer | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 15.04 上安裝 Justniffer | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 15.04 上安裝 Justniffer | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150918 Install Justniffer In Ubuntu 15.04","title":"在 Ubuntu 15.04 上安裝 Justniffer","tag":"201510","desc":""},"relativePath":"201510/20150918 Install Justniffer In Ubuntu 15.04.md","filePath":"[post].md"}'),f={name:"201510/20150918 Install Justniffer In Ubuntu 15.04.md"};function d(m,t,c,g,h,w){const n=u("Link");return l(),a("div",null,[t[16]||(t[16]=s('<h1 id="在-ubuntu-15-04-上安裝-justniffer" tabindex="-1">在 Ubuntu 15.04 上安裝 Justniffer <a class="header-anchor" href="#在-ubuntu-15-04-上安裝-justniffer" aria-label="Permalink to “在 Ubuntu 15.04 上安裝 Justniffer”">​</a></h1><h3 id="簡介" tabindex="-1">簡介 <a class="header-anchor" href="#簡介" aria-label="Permalink to “簡介”">​</a></h3><p><img src="http://1426826955.rsc.cdn77.org/wp-content/uploads/2015/09/monitoring1.jpg" alt=""></p>',3)),o("p",null,[p(n,{href:"http://sourceforge.net/projects/justniffer/?source=directory"},{default:r(()=>[...t[0]||(t[0]=[e("Justniffer",-1)])]),_:1}),t[1]||(t[1]=e(" 是一個可用於替代 Snort 的網絡協議分析器。它非常流行，可交互式地跟蹤/探測一個網絡連接。它能從實時環境中抓取流量，支持 “lipcap” 和 “tcpdump” 文件格式。它可以幫助用户分析一個用 wireshark 難以抓包的複雜網絡。尤其是它可以有效的幫助你分析應用層流量，能提取類似圖像、腳本、HTML 等 http 內容。Justniffer 有助於理解不同組件之間是如何通信的。",-1))]),t[17]||(t[17]=s(`<h3 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h3><p>Justniffer 可以收集一個複雜網絡的所有流量而不影響系統性能，這是 Justniffer 的一個優勢，它還可以保存日誌用於之後的分析，Justniffer 其它一些重要功能包括：</p><ol><li><p>可靠的 TCP 流重建</p><p>它可以使用主機 Linux 內核的一部分用於記錄並重現 TCP 片段和 IP 片段。</p></li><li><p>日誌</p><p>保存日誌用於之後的分析，並能自定義保存內容和時間。</p></li><li><p>可擴展</p><p>可以通過外部的 python、 perl 和 bash 腳本擴展來從分析報告中獲取一些額外的結果。</p></li><li><p>性能管理</p><p>基於連接時間、關閉時間、響應時間或請求時間等提取信息。</p></li></ol><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>Justniffer 可以通過 PPA 安裝：</p><p>運行下面命令添加庫：</p><pre><code>$ sudo add-apt-repository ppa:oreste-notelli/ppa
</code></pre><p>更新系統：</p><pre><code>$ sudo apt-get update
</code></pre><p>安裝 Justniffer 工具：</p><pre><code>$ sudo apt-get install justniffer
</code></pre><p>make 的時候失敗了，然後我運行下面的命令並嘗試重新安裝服務</p><pre><code>$ sudo apt-get -f install
</code></pre><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h3><p>首先用 -v 選項驗證安裝的 Justniffer 版本，你需要用超級用户權限來使用這個工具。</p><pre><code>$ sudo justniffer -V
</code></pre><p>示例輸出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/j.png" alt="j"></p><p><strong>1、 以類似 apache 的格式導出 eth1 接口流量，顯示到終端</strong></p><pre><code>$ sudo  justniffer -i eth1
</code></pre><p>示例輸出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0013.png" alt="Selection_001"></p><p><strong>2、 可以用下面的選項跟蹤正在運行的 tcp 流</strong></p><pre><code>$ sudo  justniffer -i eth1 -r
</code></pre><p>示例輸出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0023.png" alt="Selection_002"></p><p><strong>3、 獲取 web 服務器的響應時長</strong></p><pre><code>$ sudo justniffer -i eth1 -a &quot; %response.time&quot;
</code></pre><p>示例輸出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0033.png" alt="Selection_003"></p><p><strong>4、 使用 Justniffer 讀取一個 tcpdump 抓取的文件</strong></p><p>首先，用 tcpdump 抓取流量。</p><pre><code>$ sudo tcpdump -w /tmp/file.cap -s0 -i eth0
</code></pre><p>然後用 Justniffer 訪問數據</p><pre><code>$ justniffer -f file.cap
</code></pre><p>示例輸出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0056.png" alt="Selection_005"></p><p><strong>5、 只抓取 http 數據</strong></p><pre><code>$ sudo justniffer -i eth1 -r -p &quot;port 80 or port 8080&quot;
</code></pre><p>示例輸出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0064.png" alt="Selection_006"></p><p><strong>6、 獲取一個指定主機 http 數據</strong></p><pre><code>$ justniffer -i eth1 -r -p &quot;host 192.168.1.250 and tcp port 80&quot;
</code></pre><p>示例輸出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0074.png" alt="Selection_007"></p><p><strong>7、 以更精確的格式抓取數據</strong></p><p>當你輸入 <strong>justniffer -h</strong> 的時候你可以看到很多用於以更精確的方式獲取數據的格式關鍵字</p><pre><code>$ justniffer -h
</code></pre><p>示例輸出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0083.png" alt="Selection_008"></p><p>讓我們用 Justniffer 根據預先定義的參數提取數據</p><pre><code>$ justniffer -i eth1 -l &quot;%request.timestamp %request.header.host %request.url %response.time&quot;
</code></pre><p>示例輸出：</p><p><img src="http://www.unixmen.com/wp-content/uploads/2015/09/Selection_0094.png" alt="Selection_009"></p><p>其中還有很多你可以探索的選項。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Justniffer 是一個很好的用於網絡測試的工具。在我看來對於那些用 Snort 來進行網絡探測的用户來説，Justniffer 是一個更簡單的工具。它提供了很多 <strong>格式關鍵字</strong> 用於按照你的需要精確地提取數據。你可以用 .cap 文件格式記錄網絡信息，之後用於分析監視網絡服務性能。</p><p><strong>參考資料：</strong></p>`,58)),o("ul",null,[o("li",null,[p(n,{href:"http://justniffer.sourceforge.net/"},{default:r(()=>[...t[2]||(t[2]=[e("Justniffer 官網",-1)])]),_:1})])]),t[18]||(t[18]=o("hr",null,null,-1)),o("p",null,[t[4]||(t[4]=e("via: ",-1)),p(n,{href:"http://www.unixmen.com/install-justniffer-ubuntu-15-04/"},{default:r(()=>[...t[3]||(t[3]=[e("http://www.unixmen.com/install-justniffer-ubuntu-15-04/",-1)])]),_:1})]),o("p",null,[t[8]||(t[8]=e("作者：",-1)),p(n,{href:"http://www.unixmen.com/author/rajneesh/"},{default:r(()=>[...t[5]||(t[5]=[e("Rajneesh Upadhyay",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),p(n,{href:"http://mutouxiaogui.cn/blog"},{default:r(()=>[...t[6]||(t[6]=[e("ictlyh",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[13]||(t[13]=e("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創編譯，",-1)),p(n,{href:"https://linux.cn/"},{default:r(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const _=i(f,[["render",d]]);export{T as __pageData,_ as default};
